-- =============================================================================
-- Lien â€” 001_foundation.sql
-- Identity, RBAC, sessions, audit, notifications, platform settings.
--
-- Conventions used throughout the schema:
--   * UUIDv7-style time-ordered ids (generated by Postgres) for index locality.
--   * Native enums instead of free text, so invalid states are unrepresentable.
--   * timestamptz everywhere; the client renders in the viewer's zone.
--   * A partial unique index expresses "one PENDING row per pair" without
--     needing a trigger, which keeps the hot invitation path cheap.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

-- Trigram matching powers fuzzy course and name search (`similarity(...)` in the
-- academic catalogue and student discovery). Without it those queries fail at
-- parse time, so it is a hard dependency of the search feature rather than an
-- optional optimisation. Available on PostgreSQL 13+ and every managed provider.
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- =============================================================================
-- Time-ordered UUIDs (UUIDv7).
--
-- A 48-bit big-endian millisecond timestamp fills the first six bytes, so newly
-- inserted rows sort near the end of the B-tree instead of scattering across it.
-- The 48-bit clock is enough to stay monotonic until the year 10889, and the
-- 74 random bits make collisions negligible.
--
-- Layout, per RFC 9562:
--   bytes 0-5  unix_ts_ms (big endian)
--   byte  6    version 7 in the high nibble, 4 random bits below
--   byte  7    8 random bits (rand_a)
--   byte  8    variant 0b10 in the high bits (RFC 4122 layout), 6 random below
--   bytes 9-15 62 random bits (rand_b)
--
-- Note: ids are ordered by insertion *second*, not strictly monotonic within a
-- millisecond. That is the standard UUIDv7 trade-off and is sufficient for index
-- locality; a strict counter would need extra state and is not worth it here.
-- =============================================================================
CREATE OR REPLACE FUNCTION gen_uuid() RETURNS uuid
LANGUAGE sql VOLATILE AS $$
  SELECT encode(
      -- Top six bytes of the 8-byte big-endian epoch milliseconds.
      substring(int8send((extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
      || set_byte(gen_random_bytes(1), 0, 112 | (get_byte(gen_random_bytes(1), 0) & 15))  -- 0x70 = version 7
      || gen_random_bytes(1)                                                                -- rand_a
      || set_byte(gen_random_bytes(1), 0, 128 | (get_byte(gen_random_bytes(1), 0) & 63))  -- 0x80 = variant
      || gen_random_bytes(7),                                                               -- rand_b
      'hex'
    )::uuid;
$$;

-- =============================================================================
-- Enums
-- =============================================================================

CREATE TYPE user_role            AS ENUM ('STUDENT', 'LECTURER', 'ADMIN');
CREATE TYPE user_status          AS ENUM ('PENDING_VERIFICATION', 'ACTIVE', 'SUSPENDED', 'DEACTIVATED');
CREATE TYPE proficiency_level    AS ENUM ('BEGINNER', 'INTERMEDIATE', 'ADVANCED', 'EXPERT');
CREATE TYPE topic_status         AS ENUM ('NEEDS_HELP', 'LEARNING', 'COMFORTABLE', 'STRONG');
CREATE TYPE learning_goal_code   AS ENUM (
  'EXAM_PREPARATION', 'ASSIGNMENT', 'IMPROVE_UNDERSTANDING',
  'PRACTICE', 'PEER_TEACHING', 'GENERAL_REVISION', 'RESEARCH_PROJECT'
);
CREATE TYPE study_mode           AS ENUM ('ONLINE', 'PHYSICAL', 'EITHER');
CREATE TYPE study_style          AS ENUM ('DISCUSS', 'PROBLEM_SOLVING', 'TEACH_BACK', 'QUIET_FOCUS', 'MIXED');
CREATE TYPE group_privacy        AS ENUM ('PUBLIC', 'REQUEST_REQUIRED', 'INVITE_ONLY');
CREATE TYPE group_status         AS ENUM ('ACTIVE', 'ARCHIVED', 'DISBANDED');
CREATE TYPE group_member_role    AS ENUM ('OWNER', 'MODERATOR', 'MEMBER');
CREATE TYPE invitation_status    AS ENUM ('PENDING', 'ACCEPTED', 'DECLINED', 'EXPIRED', 'CANCELLED');
CREATE TYPE join_request_status  AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED');
CREATE TYPE task_status          AS ENUM ('TODO', 'IN_PROGRESS', 'COMPLETED');
CREATE TYPE task_priority        AS ENUM ('LOW', 'MEDIUM', 'HIGH');
CREATE TYPE session_mode         AS ENUM ('ONLINE', 'PHYSICAL');
CREATE TYPE session_status       AS ENUM ('SCHEDULED', 'COMPLETED', 'CANCELLED');
CREATE TYPE rsvp_status          AS ENUM ('GOING', 'MAYBE', 'NOT_GOING');
CREATE TYPE resource_kind        AS ENUM ('FILE', 'LINK', 'NOTE');
CREATE TYPE resource_visibility  AS ENUM ('GROUP', 'COURSE', 'PRIVATE');
CREATE TYPE message_kind         AS ENUM ('TEXT', 'AI', 'SYSTEM', 'RESOURCE');
CREATE TYPE recommendation_kind  AS ENUM ('GROUP', 'STUDENT');
CREATE TYPE report_status        AS ENUM ('OPEN', 'IN_REVIEW', 'RESOLVED', 'DISMISSED');
CREATE TYPE report_target_type   AS ENUM ('STUDENT', 'GROUP', 'MESSAGE', 'RESOURCE');
CREATE TYPE report_category      AS ENUM (
  'HARASSMENT', 'INAPPROPRIATE_CONTENT', 'SPAM', 'ACADEMIC_DISHONESTY', 'IMPERSONATION', 'OTHER'
);
CREATE TYPE notification_type    AS ENUM (
  'GROUP_INVITATION', 'JOIN_REQUEST', 'INVITATION_ACCEPTED', 'JOIN_REQUEST_APPROVED',
  'SESSION_REMINDER', 'SESSION_UPDATED', 'TASK_ASSIGNED', 'TASK_DUE',
  'GROUP_ANNOUNCEMENT', 'AI_RECOMMENDATION', 'SYSTEM', 'MODERATION'
);

-- =============================================================================
-- Roles â€” small lookup table rather than an enum, so admins can relabel and so
-- role assignment can be audited by id.
-- =============================================================================

CREATE TABLE roles (
  id          SMALLINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  key         user_role NOT NULL UNIQUE,
  label       TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- Users
-- =============================================================================

CREATE TABLE users (
  id                  uuid PRIMARY KEY DEFAULT gen_uuid(),
  email               citext NOT NULL,
  password_hash       TEXT,                       -- NULL for OAuth-only accounts
  role_id             SMALLINT NOT NULL REFERENCES roles(id),
  status              user_status NOT NULL DEFAULT 'PENDING_VERIFICATION',
  first_name          TEXT NOT NULL,
  last_name           TEXT NOT NULL,
  avatar_url          TEXT,
  phone               TEXT,
  locale              TEXT NOT NULL DEFAULT 'en',
  timezone            TEXT NOT NULL DEFAULT 'UTC',

  -- Account protection --------------------------------------------------
  email_verified_at   timestamptz,
  password_changed_at timestamptz,
  failed_login_count  SMALLINT NOT NULL DEFAULT 0,
  locked_until        timestamptz,
  last_login_at       timestamptz,
  must_change_password BOOLEAN NOT NULL DEFAULT FALSE,

  -- Suspension audit ----------------------------------------------------
  suspended_at        timestamptz,
  suspension_reason   TEXT,

  -- Deletion is soft so academic history stays referentially intact.
  deleted_at          timestamptz,

  -- OAuth linkage. Nullable: most accounts are email/password only.
  provider            TEXT,
  provider_subject    TEXT,

  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT users_email_shape CHECK (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  CONSTRAINT users_names_present CHECK (length(btrim(first_name)) > 0 AND length(btrim(last_name)) > 0)
);

-- Partial unique index: a suspended/deactivated account still owns its email,
-- so we must never release it for re-registration.
CREATE UNIQUE INDEX users_email_unique ON users (email) WHERE deleted_at IS NULL;
-- One account per external identity, so linking can never create a duplicate.
CREATE UNIQUE INDEX users_oauth_identity_unique ON users (provider, provider_subject)
  WHERE provider IS NOT NULL AND deleted_at IS NULL;

CREATE INDEX users_role_status_idx ON users (role_id, status) WHERE deleted_at IS NULL;
CREATE INDEX users_created_idx     ON users (created_at DESC);
CREATE INDEX users_locked_idx      ON users (locked_until) WHERE locked_until IS NOT NULL;

-- Keep updated_at honest without relying on application code.
CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER users_touch BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

-- =============================================================================
-- Sessions â€” refresh tokens are stored hashed so a database leak cannot be
-- replayed. Access tokens are stateless JWTs and never persisted.
-- =============================================================================

CREATE TABLE auth_sessions (
  id                  uuid PRIMARY KEY DEFAULT gen_uuid(),
  user_id             uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  refresh_token_hash  TEXT NOT NULL UNIQUE,
  user_agent          TEXT,
  ip_address          inet,
  device_label        TEXT,
  expires_at          timestamptz NOT NULL,
  last_used_at        timestamptz NOT NULL DEFAULT now(),
  revoked_at          timestamptz,
  revoked_reason      TEXT,
  created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX auth_sessions_user_active_idx ON auth_sessions (user_id, expires_at DESC)
  WHERE revoked_at IS NULL;
CREATE INDEX auth_sessions_expiry_idx ON auth_sessions (expires_at) WHERE revoked_at IS NULL;

-- =============================================================================
-- Single-use tokens: email verification, password reset, email change.
-- =============================================================================

CREATE TABLE auth_tokens (
  id          uuid PRIMARY KEY DEFAULT gen_uuid(),
  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose     TEXT NOT NULL CHECK (purpose IN ('EMAIL_VERIFY', 'PASSWORD_RESET', 'EMAIL_CHANGE')),
  token_hash  TEXT NOT NULL UNIQUE,
  payload     JSONB NOT NULL DEFAULT '{}'::jsonb,
  expires_at  timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX auth_tokens_user_purpose_idx ON auth_tokens (user_id, purpose, created_at DESC);

-- =============================================================================
-- Notification preferences â€” per-user, per-type, opt-out model.
-- =============================================================================

CREATE TABLE notification_preferences (
  user_id               uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  in_app_enabled        BOOLEAN NOT NULL DEFAULT TRUE,
  email_enabled         BOOLEAN NOT NULL DEFAULT TRUE,
  quiet_hours_start     SMALLINT,   -- minutes since midnight
  quiet_hours_end       SMALLINT,
  -- JSONB map of notification_type -> in-app enabled, for granular control.
  overrides             JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at            timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- Privacy settings â€” default-deny on the sensitive ones.
-- =============================================================================

CREATE TABLE privacy_settings (
  user_id               uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  profile_visibility    TEXT NOT NULL DEFAULT 'STUDENTS'
                        CHECK (profile_visibility IN ('STUDENTS', 'COURSES_ONLY', 'PRIVATE')),
  discoverable          BOOLEAN NOT NULL DEFAULT TRUE,
  allow_invites_from    TEXT NOT NULL DEFAULT 'ANY'
                        CHECK (allow_invites_from IN ('ANY', 'SHARED_GROUPS', 'NOBODY')),
  allow_messages_from   TEXT NOT NULL DEFAULT 'MEMBERS'
                        CHECK (allow_messages_from IN ('ANY', 'SHARED_GROUPS', 'MEMBERS', 'NOBODY')),
  show_availability     BOOLEAN NOT NULL DEFAULT TRUE,  -- coarse overlap only
  show_skills           BOOLEAN NOT NULL DEFAULT TRUE,
  show_full_schedule    BOOLEAN NOT NULL DEFAULT FALSE, -- never true by default
  share_progress        BOOLEAN NOT NULL DEFAULT TRUE,
  ai_personalised       BOOLEAN NOT NULL DEFAULT TRUE,  -- opt out of AI features
  updated_at            timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- Audit log â€” append-only. Written by middleware/services for security and
-- administrative events; never contains credentials.
-- =============================================================================

CREATE TABLE audit_logs (
  id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  actor_id    uuid REFERENCES users(id) ON DELETE SET NULL,
  actor_role  user_role,
  action      TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id   TEXT,
  metadata    JSONB NOT NULL DEFAULT '{}'::jsonb,
  ip_address  inet,
  user_agent  TEXT,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX audit_logs_actor_idx     ON audit_logs (actor_id, created_at DESC);
CREATE INDEX audit_logs_entity_idx    ON audit_logs (entity_type, entity_id, created_at DESC);
CREATE INDEX audit_logs_action_idx    ON audit_logs (action, created_at DESC);
CREATE INDEX audit_logs_created_idx   ON audit_logs (created_at DESC);

-- Revoke UPDATE/DELETE on the audit log to make it tamper-evident.
REVOKE UPDATE, DELETE ON audit_logs FROM PUBLIC;

-- =============================================================================
-- Notifications
-- =============================================================================

CREATE TABLE notifications (
  id          uuid PRIMARY KEY DEFAULT gen_uuid(),
  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type        notification_type NOT NULL,
  title       TEXT NOT NULL,
  body        TEXT,
  link        TEXT,
  metadata    JSONB NOT NULL DEFAULT '{}'::jsonb,
  read_at     timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX notifications_user_unread_idx ON notifications (user_id, created_at DESC)
  WHERE read_at IS NULL;
CREATE INDEX notifications_user_idx        ON notifications (user_id, created_at DESC);

-- =============================================================================
-- System settings â€” admin-editable configuration with an audit trail.
-- =============================================================================

CREATE TABLE system_settings (
  key         TEXT PRIMARY KEY,
  value       JSONB NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  updated_by  uuid REFERENCES users(id) ON DELETE SET NULL,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- Reports / moderation
-- =============================================================================

CREATE TABLE reports (
  id            uuid PRIMARY KEY DEFAULT gen_uuid(),
  reporter_id   uuid REFERENCES users(id) ON DELETE SET NULL,
  target_type   report_target_type NOT NULL,
  target_id     uuid NOT NULL,
  category      report_category NOT NULL,
  details       TEXT NOT NULL,
  status        report_status NOT NULL DEFAULT 'OPEN',
  resolution    TEXT,
  handled_by    uuid REFERENCES users(id) ON DELETE SET NULL,
  handled_at    timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX reports_status_idx  ON reports (status, created_at DESC);
CREATE INDEX reports_target_idx  ON reports (target_type, target_id);
CREATE INDEX reports_reporter_idx ON reports (reporter_id, created_at DESC);